package org.freecad.mobilelab;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.*;
import org.json.*;

/** Integration gates for candidate commands, samples, project migration and drawing sheets. */
public final class ReleaseRegression {
    static int checks;static File root,cache;interface Action{void run()throws Exception;}
    static void check(boolean b,String message){if(!b)throw new AssertionError(message);checks++;}
    static void near(double a,double b,double tolerance){check(Math.abs(a-b)<tolerance,"Expected "+b+" got "+a);}
    static void reject(Action action)throws Exception{try{action.run();}catch(Exception error){checks++;return;}throw new AssertionError("Invalid input accepted");}
    static JSONObject object(int id)throws Exception{JSONArray a=new JSONArray(NativeCad.objects());for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getInt("id")==id)return a.getJSONObject(i);throw new AssertionError("Missing object");}
    static int command(String text,int id)throws Exception{CommandLine.Request r=CommandLine.parse(text);NativeCad.beginTransaction(r.recordUndo());String workspace=ProjectStore.workspace();try{int result=CommandLine.execute(r,id);NativeCad.setWorkspace(ProjectStore.workspace());NativeCad.commitTransaction();return result;}catch(Throwable error){NativeCad.rollbackTransaction();ProjectStore.applyWorkspace(workspace);throw error;}}
    static int restore(File file)throws Exception{String workspace=ProjectStore.workspace();NativeCad.beginTransaction(false);try{int id=ProjectStore.restore(file,cache);NativeCad.commitTransaction();return id;}catch(Throwable error){NativeCad.rollbackTransaction();ProjectStore.applyWorkspace(workspace);throw error;}}
    static void manifestCopy(File from,File to,int version,boolean removeFeatures)throws Exception{try(ZipFile in=new ZipFile(from);ZipOutputStream out=new ZipOutputStream(new FileOutputStream(to))){Enumeration<? extends ZipEntry> entries=in.entries();while(entries.hasMoreElements()){ZipEntry e=entries.nextElement();byte[] bytes;try(InputStream stream=in.getInputStream(e);ByteArrayOutputStream buffer=new ByteArrayOutputStream()){ArchiveIO.copy(stream,buffer,ArchiveIO.MAX_TOTAL,null);bytes=buffer.toByteArray();}if(e.getName().equals("manifest.json")){JSONObject m=new JSONObject(new String(bytes,StandardCharsets.UTF_8));m.put("version",version);if(version==1){m.remove("minimumReader");m.remove("writer");m.remove("geometryKernel");}if(removeFeatures)m.remove("features");bytes=m.toString().getBytes(StandardCharsets.UTF_8);}out.putNextEntry(new ZipEntry(e.getName()));out.write(bytes);out.closeEntry();}}}
    public static void main(String[] args)throws Exception{
        root=args.length>0?new File(args[0]):Files.createTempDirectory("candidate-regression-").toFile();root.mkdirs();cache=new File(root,"cache");cache.mkdirs();
        String old="{\"format\":\"FreeCADMobileLab\",\"version\":1,\"units\":\"mm\",\"objects\":[]}";JSONObject migrated=ProjectSchema.read(old);check(migrated.getInt("version")==2&&migrated.getInt("minimumReader")==2,"Migration metadata");check(migrated.getJSONArray("features").length()==0,"Legacy history absent");check(new JSONObject(old).getInt("version")==1,"Source metadata rewritten");reject(()->ProjectSchema.read(old.replace("\"version\":1","\"version\":3")));reject(()->ProjectSchema.read(old.replace("\"mm\"","\"in\"")));
        NativeCad.clear();ProjectStore.reset();int ring=NativeCad.create("Ring",new double[]{18,1.6,3});NativeCad.move(ring,7,-2,4);File v2=new File(root,"v2.fcml"),v1=new File(root,"legacy.fcml");ProjectStore.save(v2,cache);manifestCopy(v2,v1,1,true);byte[] original=Files.readAllBytes(v1.toPath());check(ProjectStore.schemaVersion(v1)==1&&ProjectStore.schemaVersion(v2)==2,"Version probe");int loaded=restore(v1);near(object(loaded).getJSONArray("xyz").getDouble(0),7,.00001);near(object(loaded).getJSONArray("dims").getDouble(0),18,.00001);check(Arrays.equals(original,Files.readAllBytes(v1.toPath())),"Legacy source changed on open");ProjectStore.save(v2,cache);check(ProjectStore.schemaVersion(v2)==2,"Save did not upgrade metadata");File future=new File(root,"future.fcml");manifestCopy(v2,future,3,false);String before=NativeCad.objects();reject(()->restore(future));check(before.equals(NativeCad.objects()),"Future version changed scene");File missing=new File(root,"missing-features.fcml");manifestCopy(v2,missing,2,true);reject(()->restore(missing));
        NativeCad.clear();ProjectStore.reset();NativeCad.create("Box",new double[]{1,1,1});int exportRoot=NativeCad.create("Rectangle",new double[]{20,12});File picker=new File(root,"pending-export.fcml");ProjectStore.save(picker,cache);Map<Integer,Integer> restoredIds=new HashMap<>();NativeCad.beginTransaction(false);try{ProjectStore.restore(picker,cache,restoredIds);NativeCad.commitTransaction();}catch(Throwable e){NativeCad.rollbackTransaction();throw e;}int mapped=restoredIds.get(exportRoot);check(mapped!=exportRoot&&object(mapped).getBoolean("curve"),"Export selection did not remap to restored curve");near(object(mapped).getJSONArray("bounds").getDouble(0),20,.00001);check(!restoredIds.containsKey(Integer.MAX_VALUE),"Missing export ID appeared valid");File pickerSheet=new File(root,"restored-selection.svg");DrawingSheet.write(pickerSheet,cache,mapped,"Restored selection","");check(pickerSheet.isFile(),"Restored drawing selection failed");
        for(int i=0;i<SampleCatalog.LABELS.length;i++){NativeCad.clear();ProjectStore.reset();int id=SampleCatalog.add(i);JSONObject o=object(id);check(o.getBoolean("solid")&&o.getDouble("volume")>0,"Invalid sample "+i);int count=new JSONArray(NativeCad.objects()).length();if(i==1){JSONArray a=new JSONArray(NativeCad.objects());check(o.getDouble("volume")<a.getJSONObject(0).getDouble("volume"),"Seat removed no material");}if(i==3){int profile=new JSONArray(NativeCad.objects()).getJSONObject(0).getInt("id");FeatureModel.edit(profile,new double[]{24,12});near(object(id).getDouble("volume"),864-12*Math.PI,.0001);}File project=new File(root,String.format(Locale.US,"%02d-sample.fcml",i+1)),stl=new File(root,String.format(Locale.US,"%02d-sample.stl",i+1));ProjectStore.save(project,cache);NativeCad.write(stl.getAbsolutePath(),"stl",id);int mesh=NativeCad.read(stl.getAbsolutePath(),"stl");JSONObject report=new JSONObject(NativeCad.analyze(mesh,3));check(report.getBoolean("watertightMesh"),"Sample export not watertight");check(Math.abs(report.getDouble("volume")/object(id).getDouble("volume")-1)<.015,"Sample mesh volume drift");restore(project);check(new JSONArray(NativeCad.objects()).length()==count,"Sample project count changed");}
        for(int i=0;i<2;i++){NativeCad.clear();ProjectStore.reset();String json=SampleCatalog.graph(i);int id=ParametricGraph.evaluate(json,new int[0]);ProjectStore.graphJson=json;ProjectStore.graphOutputIds=ParametricGraph.lastOutputs.clone();check(object(id).getDouble("volume")>0,"Graph sample no volume");File project=new File(root,"graph-"+i+".fcml"),recipe=new File(root,"graph-"+i+".cadgraph");ProjectStore.save(project,cache);RecipeFiles.write(recipe,json);restore(project);check(ProjectStore.graphJson!=null&&ProjectStore.graphOutputIds.length>0,"Graph lost on reopen");ParametricGraph.validate(RecipeFiles.read(recipe));}
        NativeCad.clear();ProjectStore.reset();int line=command("Line 0 0 0 3 4 0",0);near(new JSONObject(NativeCad.analyze(line,3)).getDouble("length"),5,.0001);int arc=command("Arc 0 0 0 5 0 90",line);near(new JSONObject(NativeCad.analyze(arc,3)).getDouble("length"),2.5*Math.PI,.0001);int nurbs=command("NURBSCurve 0 0 0 1 5 8 0 2 10 0 0 1",arc);near(new JSONArray(NativeCad.curveData(nurbs)).getDouble(7),2,.0001);int interp=command("InterpCurve 0 0 0 5 8 0 10 0 0",nurbs);check(object(interp).getBoolean("curve"),"Interpolated command failed");reject(()->command("Polyline 0 0 0",interp));reject(()->command("Material 0.01 0.5",interp));command("Material 0.25 0.85",interp);near(object(interp).getJSONArray("surfaceMaterial").getDouble(1),.85,.00001);int rectangle=command("Rectangle 2 3",interp);command("Move 5 0 0",rectangle);int revolved=command("Revolve 0 0 0 0 1 0 360",rectangle);check(object(revolved).getBoolean("solid")&&object(revolved).getDouble("volume")>0,"Revolve command failed");check(CommandLine.parse("Material").ui()&&CommandLine.parse("Revolve").ui(),"No-argument dialog routing");
        NativeCad.clear();ProjectStore.reset();int profile=NativeCad.create("Rectangle",new double[]{20,12});File sheet=new File(root,"drawing-sheet.svg");DrawingSheet.write(sheet,cache,profile,"A & B <test>","Print 100%");String svg=new String(Files.readAllBytes(sheet.toPath()),StandardCharsets.UTF_8);check(svg.contains("210mm")&&svg.contains("297mm")&&svg.contains("20.000 mm")&&svg.contains("12.000 mm")&&svg.contains("Scale 1:1"),"Sheet size/dimensions");check(svg.contains("A &amp; B &lt;test&gt;"),"Sheet XML escaping");reject(()->DrawingSheet.write(sheet,cache,profile,"Bad\u0000title",""));int box=NativeCad.create("Box",new double[]{1,2,3});reject(()->DrawingSheet.write(sheet,cache,box,"Box",""));reject(()->DrawingSheet.write(sheet,cache,profile,String.join("",Collections.nCopies(101,"x")),""));int large=NativeCad.create("Rectangle",new double[]{400,300});File largeSheet=new File(root,"large-sheet.svg");DrawingSheet.write(largeSheet,cache,large,"Large drawing","Scaled, dimensions remain mm");check(new String(Files.readAllBytes(largeSheet.toPath()),StandardCharsets.UTF_8).contains("Scale 1:2.703"),"Large sheet scale");check(cache.list().length==0,"Temporary files leaked");
        System.out.println("PASS: "+checks+" candidate integration assertions: schema migration/rollback, sample solids and saved graphs, command curves/revolve/material, A4 dimensions/escaping/scaling");System.out.println("Fixtures: "+root.getAbsolutePath());
    }
}
